  #[using="nx0 e_sp0_init argH_agree SINV_agree m Hfw Hbw gb Hgb Hm ER"] Lemma cs_ok_rename : forall E cs R FULL model nx,
    csvars_all (ren_ok fw bw) cs = true -> s_log (a_ss cs) = [] ->
